function initializeInternalWebBridge() {
  // console.log('execute to initializeWebBridge');
  ZaloPayInternalJSBridge.callbackPool = ZaloPayInternalJSBridge.callbackPool || {};
  ZaloPayInternalJSBridge.subscribers = ZaloPayInternalJSBridge.subscribers || {};
  ZaloPayInternalJSBridge.subscriberId = ZaloPayInternalJSBridge.subscriberId | 0

  // call
  ZaloPayInternalJSBridge.call = function (func, param, callback) {
    if ('string' !== typeof func) {
      return;
    }

    if ('function' === typeof param) {
      callback = param;
      param = null;
    } else if (typeof param !== 'object') {
      param = null;
    }
    var clientId = '' + new Date().getTime()+(Math.random());
    if ('function' === typeof callback) {
      ZaloPayInternalJSBridge.callbackPool[clientId] = callback;
    }

    var invokeMsg = JSON.stringify({
      func: func,
      param: param,
      msgType: 'call',
      clientId: clientId
    });
    console.log("ZaloPayInternalJSBridge.callNativeFunction: " + invokeMsg);
    ZaloPayInternalJSBridge.callNativeFunction("call", invokeMsg);
  }

  // callback
  ZaloPayInternalJSBridge.callback = function (clientId, param) {
    var invokeMsg = JSON.stringify({
      clientId: clientId,
      param: param
    });
    console.log("ZaloPayInternalJSBridge.callNativeFunction: " + invokeMsg);
    ZaloPayInternalJSBridge.callNativeFunction("callback", invokeMsg);
  }

  // trigger
  ZaloPayInternalJSBridge.trigger = function (name, param, clientId) {
    if (name) {
      var evt = document.createEvent('Events');
      evt.initEvent(name, false, true);
      if (typeof param === 'object') {
        for (var k in param) {
          evt[k] = param[k];
        }
      }

      evt.clientId = clientId;
      var prevent = !document.dispatchEvent(evt);
      if (clientId && name === 'back') {
        ZaloPayInternalJSBridge.callback(clientId, {prevent: prevent});
      }if (clientId && name === 'firePullToRefresh') {
        ZaloPayInternalJSBridge.callback(clientId, {prevent: prevent});
      }
    }
  }

  // _invokeJS
  ZaloPayInternalJSBridge._invokeJS = function (resp) {
    resp = resp.replace("&quot;", "'");
    resp = JSON.parse(resp);
//     console.log("invokeJS msgType " + resp.msgType + " func " + resp.func + " clientId " + resp.clientId);
    if (resp.msgType === 'callback') {
      var func = ZaloPayInternalJSBridge.callbackPool[resp.clientId];
      if (!(typeof resp.keepCallback == 'boolean' && resp.keepCallback)) {
        delete ZaloPayInternalJSBridge.callbackPool[resp.clientId];
      }
      if ('function' === typeof func) {
        setTimeout(function () {
          func(resp.param);
        }, 1);
      }
    } else if (resp.msgType === 'call') {
      resp.func && this.trigger(resp.func, resp.param, resp.clientId);
    }
  }

  ZaloPayInternalJSBridge.subscribe = function(event, callback) {
      var id = ZaloPayInternalJSBridge.subscriberId;
      ZaloPayInternalJSBridge.subscriberId = id + 1
      ZaloPayInternalJSBridge.subscribers[id] = {event: event, callback: callback}
      ZaloPayInternalJSBridge.call("register", {event}, null)
      return id
  }

  ZaloPayInternalJSBridge.fire = function(event, params) {
      for (var id in ZaloPayInternalJSBridge.subscribers) {
          var subscriber = ZaloPayInternalJSBridge.subscribers[id]

          if (subscriber.event == event)
              subscriber.callback(params);
      }
  }

  ZaloPayInternalJSBridge.unsubscribe = function(id) {
      var subscribed = (ZaloPayInternalJSBridge.subscribers[id]) ? true : false;
      if (subscribed) {
          delete ZaloPayInternalJSBridge.subscribers[id];
      }
  }

  var readyEvent = document.createEvent('Events');
  readyEvent.initEvent('ZaloPayInternalJSBridgeReady', false, false);
  document.dispatchEvent(readyEvent);
  console.log("DONE initializing ZaloPayInternalJSBridge")
};

